        return (n - rank) / n

    def gaussian_elimination(matrix):
        # Perform Gaussian elimination to find the rank of the matrix
        n = len(matrix)
        for i in range(n):
            max_row = i
            for j in range(i+1, n):
                if abs(matrix[j][i]) > abs(matrix[max_row][i]):
